Add-ShimsDirToPath
# Setup initial configuration of Scoop
Add-DefaultConfig

Write-InstallInfo 'Scoop was installed successfully!' -ForegroundColor DarkGreen
Write-InstallInfo &quot;Type 'scoop help' for instructions.&quot;

}
