Write-Verbose &quot;SCOOP_CACHE_DIR: $SCOOP_CACHE_DIR&quot;
Write-Verbose &quot;SCOOP_GLOBAL_DIR: $SCOOP_GLOBAL_DIR&quot;
Write-Verbose &quot;SCOOP_CONFIG_HOME: $SCOOP_CONFIG_HOME&quot;

}
